WITH sales_agg AS ( SELECT cs.cs_item_sk, SUM(cs.cs_ext_sales_price) AS total_sales_amount, SUM(cs.cs_net_profit) AS total_sales_profit FROM catalog_sales cs GROUP BY cs.cs_item_sk ), returns_agg AS ( SELECT cr.cr_item_sk, SUM(cr.cr_return_amount) AS total_return_amount, SUM(cr.cr_net_loss) AS total_return_loss FROM catalog_returns cr GROUP BY cr.cr_item_sk ), sales_demo_agg AS ( SELECT cs.cs_item_sk, AVG(CAST(hd.hd_income_band_sk AS DOUBLE)) AS avg_income_band, AVG(CAST(hd.hd_vehicle_count AS DOUBLE)) AS avg_vehicle_count FROM catalog_sales cs JOIN household_demographics hd ON cs.cs_bill_hdemo_sk = hd.hd_demo_sk GROUP BY cs.cs_item_sk ) SELECT i.i_item_sk, i.i_product_name, i.i_category, COALESCE(sa.total_sales_amount, 0) AS total_sales_amount, COALESCE(ra.total_return_amount, 0) AS total_return_amount, COALESCE(sa.total_sales_profit, 0) - COALESCE(ra.total_return_loss, 0) AS net_profit_after_returns, d.avg_income_band, d.avg_vehicle_count, CASE WHEN COALESCE(sa.total_sales_profit, 0) - COALESCE(ra.total_return_loss, 0) > 1000 THEN 'HIGH' WHEN COALESCE(sa.total_sales_profit, 0) - COALESCE(ra.total_return_loss, 0) BETWEEN 0 AND 1000 THEN 'MEDIUM' ELSE 'LOW' END AS profit_category, RANK() OVER (ORDER BY COALESCE(sa.total_sales_profit, 0) - COALESCE(ra.total_return_loss, 0) DESC) AS profit_rank FROM item i LEFT JOIN sales_agg sa ON i.i_item_sk = sa.cs_item_sk LEFT JOIN returns_agg ra ON i.i_item_sk = ra.cr_item_sk LEFT JOIN sales_demo_agg d ON i.i_item_sk = d.cs_item_sk ORDER BY net_profit_after_returns DESC LIMIT 50
